import math

def check_n(n):
    """
    Checks the condition for a given integer n.
    Condition: For all a such that floor(n/a) = 2,
    binom(a-1, n-2a-1) must be divisible by n-2a.
    """
    if n < 5 or n % 2 == 0 or n % 3 == 0:
        return False # Pre-filter based on initial findings

    # Determine the range for a: n/3 < a <= n/2
    a_min = math.floor(n / 3) + 1
    a_max = math.floor(n / 2)

    results = {}
    all_pass = True

    for a in range(a_min, a_max + 1):
        r = n - 2 * a  # r = n - 2a. This is the divisor and the index shift.

        # The required binomial coefficient is C(a-1, n-2a-1) = C(a-1, r-1)
        k_upper = a - 1
        k_lower = r - 1

        # Constraint check: k_lower must be non-negative.
        if k_lower < 0:
            # If r <= 0, then n - 2a <= 0, meaning 2a >= n. Since a <= n/2, this is only true at a=n/2 
            # if n is even, but we filtered even n. If n is odd, a <= (n-1)/2, so 2a <= n-1, r >= 1.
            # If n is prime > 2, r >= 1 for all valid a.
            # If r=1, k_lower=0, C(..., 0) = 1. Divisibility by 1 holds.
            if r == 1:
                C = 1
            else:
                # This case should not happen for odd n >= 5
                print(f"Warning: Negative lower index for n={n}, a={a}, r={r}")
                continue 
        else:
            # We use math.comb for binomial coefficient C(k_upper, k_lower)
            # Note: if k_lower > k_upper, the combination is 0.
            C = math.comb(k_upper, k_lower)

        divisor = r

        if divisor == 0:
             # Should not happen for odd n >= 5
             print(f"Error: Divisor is zero for n={n}, a={a}")
             all_pass = False
             break

        is_divisible = (C % divisor == 0)

        results[a] = {
            'r': r,
            'C': C,
            'is_divisible': is_divisible
        }

        if not is_divisible:
            all_pass = False
            break

    return all_pass, results

